import{_ as i,o as a,c as t,ae as o}from"./chunks/framework.1Lna8NcP.js";const h=JSON.parse('{"title":"ADR-004: User Profile and AI-Powered Guidance","description":"","frontmatter":{},"headers":[],"relativePath":"adr/004-user-profile-and-ai-guidance.md","filePath":"adr/004-user-profile-and-ai-guidance.md"}'),r={name:"adr/004-user-profile-and-ai-guidance.md"};function n(s,e,l,d,c,u){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-004-user-profile-and-ai-powered-guidance" tabindex="-1">ADR-004: User Profile and AI-Powered Guidance <a class="header-anchor" href="#adr-004-user-profile-and-ai-powered-guidance" aria-label="Permalink to &quot;ADR-004: User Profile and AI-Powered Guidance&quot;">​</a></h1><p><strong>Date:</strong> 2026-04-05 <strong>Status:</strong> Accepted</p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>ADR-001&#39;s Insights page mentioned an optional Claude API chat. This ADR formalizes a broader decision: collect a rich user profile in Settings and use it to power personalized, jurisdiction-aware guidance across the entire app — Insights, Taxes, and Projections.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><h3 id="user-profile-stored-in-settings-table" tabindex="-1">User Profile (stored in <code>settings</code> table) <a class="header-anchor" href="#user-profile-stored-in-settings-table" aria-label="Permalink to &quot;User Profile (stored in `settings` table)&quot;">​</a></h3><p>Collect the following to personalize guidance:</p><ul><li>Date of birth, country, state/province</li><li>Tax filing status, estimated income by type (W-2, 1099, rental)</li><li>Current business entity (none / sole prop / LLC / S-Corp / other)</li><li>Risk profile, monthly expenses, retirement target age and amount</li></ul><p>This profile is passed as context to the Claude API for any AI-powered feature.</p><h3 id="guidance-tiers" tabindex="-1">Guidance Tiers <a class="header-anchor" href="#guidance-tiers" aria-label="Permalink to &quot;Guidance Tiers&quot;">​</a></h3><p><strong>Rule-based (no API key required):</strong></p><ul><li>Tax estimates, tax-loss harvesting flags, insight cards, projection curves</li><li>Uses user profile for jurisdiction-specific rules</li></ul><p><strong>AI-powered (opt-in, requires <code>CLAUDE_API_KEY</code> in <code>.env</code>):</strong></p><ul><li>Insights chat (full portfolio + profile as context)</li><li>Entity structure recommendations (reasoning + estimated savings + setup checklist)</li><li>Complex tax strategy interpretation</li></ul><h3 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h3><ul><li>User profile stored only in local SQLite DB</li><li>Claude API calls are made server-side; only relevant slices of data are sent (not the full DB)</li><li>API key in <code>.env</code>, gitignored</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Settings page gains a &quot;User Profile&quot; section</li><li>New settings keys added to <code>settings</code> table (see spec for full list)</li><li>Backend profile-aware logic in <code>insights.py</code> and new <code>taxes.py</code> router</li><li>Claude API integration centralized in a new <code>ai.py</code> utility module</li><li><code>.env.example</code> documents <code>CLAUDE_API_KEY</code> without a real value</li></ul>',19)])])}const f=i(r,[["render",n]]);export{h as __pageData,f as default};
